-- federationExchange
DO $authz$
DECLARE p record;
BEGIN
  FOR p IN SELECT policyname FROM pg_policies WHERE schemaname = 'public' AND tablename = 'federationExchange' LOOP
    EXECUTE format('DROP POLICY %I ON public.%I', p.policyname, 'federationExchange');
  END LOOP;
END
$authz$;
ALTER TABLE public."federationExchange" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "SELECT" ON "public"."federationExchange" FOR SELECT USING ("companyId" = ANY ((SELECT get_companies_with_employee_permission('settings_view'))::text[]));

